package cn.mop.persistence;

import cn.mop.domain.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

/** Real authorized bounded main-ledger reads. No new schema, role mutation, fixture or monitoring observation. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresAssetReadIntegrationTest {
    static final String TENANT="55000000-0000-4000-8000-000000000001",OTHER="55000000-0000-4000-8000-000000000002";
    static HikariDataSource pool;static PostgresPlatformRepository platform;static String engineer;
    @BeforeAll static void connect(){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(3);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);platform=new PostgresPlatformRepository(pool,new ObjectMapper().findAndRegisterModules());engineer=actor("msp");}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    static String actor(String role){return platform.users().stream().filter(u->platform.membership(u.id(),TENANT).filter(m->m.role().equals(role)).isPresent()).findFirst().orElseThrow().id();}
    static long permission(String actor){return platform.membership(actor,TENANT).orElseThrow().permissionVersion();}
    static Asset create(String name,String type,String ip){String key=UUID.randomUUID().toString();return (Asset)platform.idempotent(engineer,TENANT,"POST /integration/ledger-read",key,"a".repeat(64),()->{var asset=platform.insert(TENANT,engineer,name,type,ip,"site-a-main");platform.audit(engineer,TENANT,"integration.asset_read.create","asset",asset.id(),"SUCCEEDED","SYNTHETIC_ONLY",key);return asset;});}
    static AssetReadQuery query(String q,int limit){return new AssetReadQuery(null,null,null,q,limit,null,null);}
    static long audits()throws SQLException{try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT count(*) FROM public.mop_audit")){r.next();return r.getLong(1);}}
    @Test void queryExecutesBoundedAscendingCreationKeysetInsteadOfWholeTenantMaterialization(){String prefix="LEDGER-BOUND-"+UUID.randomUUID();List<Asset> created=new ArrayList<>();for(int i=0;i<4;i++)created.add(create(prefix+"-"+i,"router","192.0.2.91"));var first=platform.authorizedAssets(TENANT,engineer,permission(engineer),query(prefix,2));assertEquals(2,first.size());Asset tail=first.get(1);var second=platform.authorizedAssets(TENANT,engineer,permission(engineer),new AssetReadQuery(null,null,null,prefix,2,tail.createdAt(),tail.id()));assertEquals(2,second.size());assertEquals(created.stream().map(Asset::id).toList(),java.util.stream.Stream.concat(first.stream(),second.stream()).map(Asset::id).toList());}
    @Test void exactFiltersAndLiteralNameSubstringsStayConjunctive(){String prefix="LEDGER-LITERAL-"+UUID.randomUUID();Asset one=create(prefix+"-%_ÄBC","switch","192.0.2.92");create(prefix+"-zzÄBC","router","192.0.2.93");var filter=new AssetReadQuery("switch","unknown","site-a-main",prefix.toLowerCase()+"-%_äbc",10,null,null);assertEquals(List.of(one.id()),platform.authorizedAssets(TENANT,engineer,permission(engineer),filter).stream().map(Asset::id).toList());assertTrue(platform.authorizedAssets(TENANT,engineer,permission(engineer),query(prefix+"' OR '1'='1",10)).isEmpty());assertTrue(platform.authorizedAssets(TENANT,engineer,permission(engineer),new AssetReadQuery("switch","ok","site-a-main",prefix,10,null,null)).isEmpty());}
    @Test void ipSubstringRetainsCaseSensitiveLiteralSemantics(){String address="2001:db8:"+UUID.randomUUID().toString().substring(0,4)+"::AB";Asset asset=create("LEDGER-IP-"+UUID.randomUUID(),"router",address);assertEquals(List.of(asset.id()),platform.authorizedAssets(TENANT,engineer,permission(engineer),query(address,10)).stream().map(Asset::id).toList());assertTrue(platform.authorizedAssets(TENANT,engineer,permission(engineer),query(address.toLowerCase(),10)).stream().noneMatch(a->a.id().equals(asset.id())));}
    @Test void everyExistingKnownRoleReadsOnlyCurrentTenantAssets(){Asset asset=create("LEDGER-ROLES-"+UUID.randomUUID(),"router","192.0.2.94");for(String role:List.of("msp","padmin","tadmin","viewer")){String user=actor(role);assertEquals(asset,platform.authorizedAsset(TENANT,user,permission(user),asset.id()).orElseThrow());assertEquals(List.of(asset.id()),platform.authorizedAssets(TENANT,user,permission(user),query(asset.name(),10)).stream().map(Asset::id).toList());}String foreign=platform.list(OTHER).get(0).id();assertTrue(platform.authorizedAsset(TENANT,engineer,permission(engineer),foreign).isEmpty());assertTrue(platform.authorizedAssets(TENANT,engineer,permission(engineer),new AssetReadQuery(null,null,"site-b-main",null,10,null,null)).isEmpty());}
    @Test void staleAndMissingMembershipFailBeforeReturningEvenAnUnknownObject(){assertEquals(401,assertThrows(DomainException.class,()->platform.authorizedAssets(TENANT,engineer,permission(engineer)+1,query(null,10))).status);assertEquals(401,assertThrows(DomainException.class,()->platform.authorizedAsset(TENANT,engineer,permission(engineer)+1,"not-a-uuid")).status);assertEquals(401,assertThrows(DomainException.class,()->platform.authorizedAssets(TENANT,UUID.randomUUID().toString(),1,query(null,10))).status);}
    @Test void malformedOrWrongAssetIdDoesNotRevealOtherObjectsAndCanonicalUuidIsAccepted(){Asset asset=create("LEDGER-ID-"+UUID.randomUUID(),"router","192.0.2.95");assertEquals(asset,platform.authorizedAsset(TENANT,engineer,permission(engineer),asset.id().toUpperCase()).orElseThrow());assertTrue(platform.authorizedAsset(TENANT,engineer,permission(engineer),"not-a-uuid").isEmpty());assertTrue(platform.authorizedAsset(TENANT,engineer,permission(engineer),UUID.randomUUID().toString()).isEmpty());}
    @Test void successfulReadDoesNotChangeAssetOrAuditAndEmptyFilterStringsAreExplicit()throws SQLException{Asset asset=create("LEDGER-READONLY-"+UUID.randomUUID(),"router","192.0.2.96");long before=audits();var read=platform.authorizedAsset(TENANT,engineer,permission(engineer),asset.id()).orElseThrow();assertEquals(asset,read);assertFalse(platform.authorizedAssets(TENANT,engineer,permission(engineer),query("",1)).isEmpty());assertTrue(platform.authorizedAssets(TENANT,engineer,permission(engineer),new AssetReadQuery(null,null,"",null,10,null,null)).isEmpty());assertEquals(before,audits());}
    @Test void existingIcuExpressionHandlesUnicodeWithoutChangingDatabaseLocaleOrStoredText()throws SQLException{
        String before;try(var c=pool.getConnection();var st=c.createStatement();var r=st.executeQuery("SELECT datcollate||'|'||datctype FROM pg_database WHERE datname=current_database()")){r.next();before=r.getString(1);assertTrue(PostgresUnicodeSearch.ready(c));}assertEquals(List.of(),platform.assetReadProblems());
        String prefix="LEDGER-UNICODE-"+UUID.randomUUID();for(String suffix:List.of("Ä","ΟΣ","İ","K")){Asset asset=create(prefix+"-"+suffix,"router","192.0.2.98");String q=(prefix+"-"+suffix).toLowerCase(Locale.ROOT);assertTrue(platform.authorizedAssets(TENANT,engineer,permission(engineer),query(q,10)).stream().anyMatch(a->a.id().equals(asset.id())));assertEquals(prefix+"-"+suffix,platform.authorizedAsset(TENANT,engineer,permission(engineer),asset.id()).orElseThrow().name());}
        Asset composed=create(prefix+"-É","router","192.0.2.99");assertTrue(platform.authorizedAssets(TENANT,engineer,permission(engineer),query(prefix+"-e\u0301",10)).stream().noneMatch(a->a.id().equals(composed.id())));try(var c=pool.getConnection();var st=c.createStatement();var r=st.executeQuery("SELECT datcollate||'|'||datctype FROM pg_database WHERE datname=current_database()")){r.next();assertEquals(before,r.getString(1));}
    }

}
